-- Real SQL behavior, not a source-string assertion. Only synthetic fixture data.
create table public.qa_results(name text);
grant select,insert on qa_results to authenticated,anon;
set role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',false);
do $$
declare p uuid; p2 uuid; r uuid; r2 uuid; g uuid; s uuid; f uuid; e uuid; out jsonb; k uuid; n integer; t jsonb;
begin
 select id into p from public.bite_properties where origin_restaurant_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
 assert p is not null,'Backfill missing';
 assert jsonb_array_length(public.bite_owner_context())=1,'Context leaks another property';
 assert not private.bite_can(p,'hotel_rooms'),'Restaurant unexpectedly has hotel';
 insert into qa_results values('A061 A091 A095: restaurant non-destructive default and isolated context');
 begin
  perform public.bite_property_command(p,'room_save','{"number":"1","room_type":"Deluxe","nightly_rate":100,"adults":2}',gen_random_uuid());
  raise exception 'Expected hotel permission denial';
 exception when insufficient_privilege then null; end;
 insert into qa_results values('A070 A109: hidden hotel RPC denied');
 p2:=public.bite_create_property('Synthetic Hotel','hotel','99999999-9999-4999-8999-999999999999');
 assert public.bite_create_property('Synthetic Hotel','hotel','99999999-9999-4999-8999-999999999999')=p2;
 assert jsonb_array_length(public.bite_owner_context())=2;
 p:=p2;
 insert into qa_results values('A092 A105 A106: hotel-only and two property contexts');
 out:=public.bite_property_command(p,'room_save','{"number":"101","room_type":"Deluxe","nightly_rate":1000,"adults":2,"children":2}',gen_random_uuid());r:=(out->>'id')::uuid;
 out:=public.bite_property_command(p,'room_save','{"number":"102","room_type":"Suite","nightly_rate":1500,"adults":3,"children":2}',gen_random_uuid());r2:=(out->>'id')::uuid;
 out:=public.bite_property_command(p,'guest_save','{"full_name":"Synthetic Guest","phone":"9999999999","id_type":"Passport","id_last4":"1234"}',gen_random_uuid());g:=(out->>'id')::uuid;
 insert into qa_results values('A006 A007 A008: occupancy, optional email, minimal ID');
 k:=gen_random_uuid();out:=jsonb_build_object('guest_id',g,'room_id',r,'arrival',current_date,'departure',current_date+2,'adults',2,'children',1);
 t:=public.bite_property_command(p,'reserve',out,k);s:=(t->>'id')::uuid;f:=(t->>'folio_id')::uuid;
 assert public.bite_property_command(p,'reserve',out,k)=t;
 begin perform public.bite_property_command(p,'reserve',out,gen_random_uuid());raise exception 'Expected conflict';exception when raise_exception then if sqlerrm='Expected conflict' then raise;end if;end;
 begin perform public.bite_property_command(p,'reserve',out||'{"children":9}'::jsonb,gen_random_uuid());raise exception 'Expected occupancy failure';exception when raise_exception then if sqlerrm='Expected occupancy failure' then raise;end if;end;
 insert into qa_results values('A011 A113: room collision and duplicate reservation rejected');
 perform public.bite_property_command(p,'room_status',jsonb_build_object('id',r,'status','dirty'),gen_random_uuid());
 begin perform public.bite_property_command(p,'checkin',jsonb_build_object('id',s),gen_random_uuid());raise exception 'Expected dirty denial';exception when raise_exception then if sqlerrm='Expected dirty denial' then raise;end if;end;
 perform public.bite_property_command(p,'room_status',jsonb_build_object('id',r,'status','ready'),gen_random_uuid());
 perform public.bite_property_command(p,'checkin',jsonb_build_object('id',s),gen_random_uuid());
 perform public.bite_property_command(p,'checkin',jsonb_build_object('id',s),gen_random_uuid());
 select count(*) into n from public.bite_folio_entries where folio_id=f and category='room';assert n=1;
 insert into qa_results values('A001 A013 A021 A059: check-in, nightly rent, dirty-room denial and repeat check-in');
 perform public.bite_property_command(p,'move',jsonb_build_object('id',s,'room_id',r2),gen_random_uuid());
 assert (select housekeeping from public.bite_rooms where id=r)='dirty';
 assert (select stay_id from public.bite_folios where id=f)=s;
 perform public.bite_property_command(p,'extend',jsonb_build_object('id',s,'departure',current_date+3),gen_random_uuid());
 assert (select departure from public.bite_stays where id=s)=current_date+3;
 insert into qa_results values('A015 A016 A087: move/extend keep stay and folio linkage');
 k:=gen_random_uuid();out:=jsonb_build_object('folio_id',f,'amount',50,'description','Water bottle');
 t:=public.bite_property_command(p,'charge',out,k);e:=(t->>'id')::uuid;
 assert public.bite_property_command(p,'charge',out,k)=t;
 begin perform public.bite_property_command(p,'charge',out||'{"amount":51}'::jsonb,k);raise exception 'Expected idempotency conflict';exception when raise_exception then if sqlerrm='Expected idempotency conflict' then raise;end if;end;
 perform public.bite_property_command(p,'reverse',jsonb_build_object('id',e,'folio_id',f,'description','Wrong bottle'),gen_random_uuid());
 perform public.bite_property_command(p,'charge',jsonb_build_object('folio_id',f,'amount',100,'description','Laundry'),gen_random_uuid());
 insert into qa_results values('A022 A023 A038: incidentals and exactly-once ledger');
 perform public.bite_property_command(p,'deposit_hold',jsonb_build_object('folio_id',f,'amount',500,'description','Security deposit','method','Cash'),gen_random_uuid());
 perform public.bite_property_command(p,'deposit_apply',jsonb_build_object('folio_id',f,'amount',100,'description','Apply deposit'),gen_random_uuid());
 perform public.bite_property_command(p,'deposit_return',jsonb_build_object('folio_id',f,'amount',400,'description','Cash returned','method','Cash'),gen_random_uuid());
 out:=public.bite_property_command(p,'payment',jsonb_build_object('folio_id',f,'amount',500,'description','UPI transfer','method','UPI'),gen_random_uuid());e:=(out->>'id')::uuid;
 begin perform public.bite_property_command(p,'checkout',jsonb_build_object('folio_id',f),gen_random_uuid());raise exception 'Expected unsettled denial';exception when raise_exception then if sqlerrm='Expected unsettled denial' then raise;end if;end;
 assert (select status from public.bite_folio_entries where id=e)='pending';
 perform public.bite_property_command(p,'payment_confirm',jsonb_build_object('id',e,'folio_id',f,'reference','TEST-VERIFIED-REF'),gen_random_uuid());
 perform public.bite_property_command(p,'payment',jsonb_build_object('folio_id',f,'amount',2500,'description','Cash balance','method','Cash'),gen_random_uuid());
 insert into qa_results values('A032 A033 A035: pending UPI, split collection and deposit accounting');
 t:=public.bite_hotel_workspace(p);
 assert ((t->'folios'->0->'totals')->>'balance')::numeric=0;
 assert ((t->'folios'->0->'totals')->>'deposit_held')::numeric=0;
 perform public.bite_property_command(p,'checkout',jsonb_build_object('folio_id',f),gen_random_uuid());
 out:=public.bite_property_command(p,'checkout',jsonb_build_object('folio_id',f),gen_random_uuid());
 assert (out->>'already_complete')::boolean;
 assert (select housekeeping from public.bite_rooms where id=r2)='dirty';
 assert (select invoice_snapshot->>'number' from public.bite_folios where id=f) is not null;
 begin perform public.bite_property_command(p,'charge',jsonb_build_object('folio_id',f,'amount',1,'description','Late mutation'),gen_random_uuid());raise exception 'Expected immutable denial';exception when raise_exception then if sqlerrm='Expected immutable denial' then raise;end if;end;
 insert into qa_results values('A029 A041 A049 A050 A051: checkout/invoice immutable and Dirty exactly once');
 perform public.bite_property_command(p,'member','{"id":"33333333-3333-4333-8333-333333333333","role":"receptionist","active":true}',gen_random_uuid());
 perform public.bite_property_command(p,'member','{"id":"44444444-4444-4444-8444-444444444444","role":"housekeeping","active":true}',gen_random_uuid());
 perform public.bite_property_command(p,'member','{"id":"55555555-5555-4555-8555-555555555555","role":"accountant","active":true}',gen_random_uuid());
 perform public.bite_property_command(p,'member','{"id":"77777777-7777-4777-8777-777777777777","role":"cashier","active":true}',gen_random_uuid());
end $$;
select set_config('request.jwt.claim.sub','44444444-4444-4444-8444-444444444444',false);
do $$ declare p uuid; r uuid; begin
 select id into p from public.bite_properties where name='Synthetic Hotel';
